# Generated by agent-harness-tui (create-only; edit freely).
# Manages agent.db next to this script. completed.log is the source of
# truth for completed instructions: this script only appends to it.
# Requires the sqlite3 CLI. Author: $env:AGENT_DB_ACTOR (default: agent).
# Works on Windows PowerShell 5.1 and PowerShell 7+.
$ErrorActionPreference = 'Stop'
$argv = @($args)

$dir = $PSScriptRoot
$db = Join-Path $dir 'agent.db'
$log = Join-Path $dir 'completed.log'
$actor = if ($env:AGENT_DB_ACTOR) { $env:AGENT_DB_ACTOR } else { 'agent' }
$utf8 = New-Object System.Text.UTF8Encoding($false)
$OutputEncoding = $utf8
[Console]::OutputEncoding = $utf8

function Show-Usage {
  @'
usage: agent-db.ps1 init | verify | schema | timestamp | reconcile
       agent-db.ps1 backlog-list
       agent-db.ps1 backlog-add <title> [description]
       agent-db.ps1 backlog-complete <id>
       agent-db.ps1 instruction-list
       agent-db.ps1 instruction-show <uuid>
       agent-db.ps1 instruction-upsert <uuid> <title>
       agent-db.ps1 instruction-complete <uuid> <summary>
'@ | Write-Host
  exit 2
}

function Fail([string]$msg) { [Console]::Error.WriteLine("error: $msg"); exit 1 }
function Q([string]$v) { "'" + $v.Replace("'", "''") + "'" }
function Now { (Get-Date).ToString('yyyy-MM-dd HH:mm:ss ') + ((Get-Date).ToString('zzz') -replace ':', '') }
function OneLine([string]$name, [string]$v) {
  if (-not $v -or $v.Contains('|') -or $v.Contains("`n") -or $v.Contains("`r")) { Fail "$name must be one non-empty line without '|'" }
}

if (-not (Get-Command sqlite3 -ErrorAction SilentlyContinue)) { Fail 'sqlite3 CLI not found; install it to use this script' }

# SQL always goes through stdin: native argument quoting differs between
# PowerShell versions.
function Sql([string]$text, [switch]$Table) {
  if ($Table) { $text = ".headers on`n.mode column`n" + $text }
  $out = $text | & sqlite3 -bail $db
  if ($LASTEXITCODE -ne 0) { Fail "sqlite3 failed ($LASTEXITCODE)" }
  $out
}

function Init-Schema {
  Sql @'
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS backlog (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'created',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_by TEXT
);
CREATE TABLE IF NOT EXISTS instructions (
  uuid TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'created',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_backlog_status ON backlog(status);
CREATE INDEX IF NOT EXISTS idx_instructions_status ON instructions(status);
'@ | Out-Null
}

function Get-LogUuid([string]$line) { $line.Split('|')[0].Trim() }

# Marks every instruction listed in completed.log as completed.
function Reconcile {
  Init-Schema
  if (-not (Test-Path -LiteralPath $log)) { return }
  $t = Now
  $sb = New-Object System.Text.StringBuilder
  [void]$sb.AppendLine('.timeout 5000')
  [void]$sb.AppendLine('BEGIN IMMEDIATE;')
  foreach ($line in [IO.File]::ReadAllLines($log, $utf8)) {
    if (-not $line.Trim() -or $line.StartsWith('#')) { continue }
    $first = $line.IndexOf('|'); $last = $line.LastIndexOf('|')
    if ($first -lt 0 -or $first -eq $last) { Fail "invalid completed.log line: $line" }
    $uuid = $line.Substring(0, $first).Trim()
    $summary = $line.Substring($first + 1, $last - $first - 1).Trim()
    $ts = $line.Substring($last + 1).Trim()
    [void]$sb.AppendLine("INSERT INTO instructions(uuid,title,status,created_at,updated_at,created_by,updated_by) VALUES($(Q $uuid),$(Q $summary),'completed',$(Q $ts),$(Q $ts),'completed.log','completed.log') ON CONFLICT(uuid) DO UPDATE SET status='completed',updated_at=$(Q $t),updated_by='completed.log' WHERE status<>'completed';")
  }
  [void]$sb.AppendLine('COMMIT;')
  Sql $sb.ToString() | Out-Null
}

$cmd = if ($argv.Count -gt 0) { $argv[0] } else { '' }
switch ($cmd) {
  { $_ -in 'init', 'reconcile' } { Reconcile; break }
  'schema' { Init-Schema; Sql '.schema'; break }
  'timestamp' { Now; break }
  'verify' {
    Reconcile
    Sql "PRAGMA integrity_check; SELECT 'backlog' AS tbl, status, COUNT(*) AS rows FROM backlog GROUP BY status UNION ALL SELECT 'instructions', status, COUNT(*) FROM instructions GROUP BY status;" -Table
    break
  }
  'backlog-list' {
    Reconcile
    Sql "SELECT id,title,description,created_at,status FROM backlog WHERE status='created' ORDER BY id;" -Table
    break
  }
  'backlog-add' {
    if ($argv.Count -lt 2 -or $argv.Count -gt 3) { Show-Usage }
    Reconcile
    $t = Now
    $desc = if ($argv.Count -eq 3) { Q $argv[2] } else { 'NULL' }
    Sql "INSERT INTO backlog(title,description,status,created_at,updated_at,created_by,updated_by) VALUES($(Q $argv[1]),$desc,'created',$(Q $t),$(Q $t),$(Q $actor),$(Q $actor)); SELECT last_insert_rowid();"
    break
  }
  'backlog-complete' {
    if ($argv.Count -ne 2 -or "$($argv[1])" -notmatch '^[0-9]+$') { Show-Usage }
    Reconcile
    $n = Sql "UPDATE backlog SET status='completed',updated_at=$(Q (Now)),updated_by=$(Q $actor) WHERE id=$($argv[1]); SELECT changes();"
    if ("$n".Trim() -ne '1') { Fail "backlog id not found: $($argv[1])" }
    break
  }
  'instruction-list' {
    Reconcile
    Sql 'SELECT uuid,title,status,created_at,updated_at FROM instructions ORDER BY created_at,uuid;' -Table
    break
  }
  'instruction-show' {
    if ($argv.Count -ne 2) { Show-Usage }
    Reconcile
    Sql "SELECT uuid,title,status,created_at,updated_at,created_by,updated_by FROM instructions WHERE uuid=$(Q $argv[1]);" -Table
    break
  }
  'instruction-upsert' {
    if ($argv.Count -ne 3) { Show-Usage }
    OneLine 'uuid' $argv[1]; OneLine 'title' $argv[2]
    Reconcile
    $t = Now
    Sql "INSERT INTO instructions(uuid,title,status,created_at,updated_at,created_by,updated_by) VALUES($(Q $argv[1]),$(Q $argv[2]),'created',$(Q $t),$(Q $t),$(Q $actor),$(Q $actor)) ON CONFLICT(uuid) DO UPDATE SET title=excluded.title,updated_at=excluded.updated_at,updated_by=excluded.updated_by WHERE status<>'completed';" | Out-Null
    break
  }
  'instruction-complete' {
    if ($argv.Count -ne 3) { Show-Usage }
    $uuid = "$($argv[1])"; $summary = "$($argv[2])"
    OneLine 'uuid' $uuid; OneLine 'summary' $summary
    Reconcile
    if (Test-Path -LiteralPath $log) {
      foreach ($line in [IO.File]::ReadAllLines($log, $utf8)) {
        if ($line.Contains('|') -and (Get-LogUuid $line) -eq $uuid) { Fail "already in completed.log: $uuid" }
      }
    }
    # Append only; never rewrite existing lines.
    $prefix = ''
    if ((Test-Path -LiteralPath $log) -and (Get-Item -LiteralPath $log).Length -gt 0) {
      $bytes = [IO.File]::ReadAllBytes($log)
      if ($bytes[$bytes.Length - 1] -ne 10) { $prefix = "`n" }
    }
    [IO.File]::AppendAllText($log, "$prefix$uuid | $summary | $(Now)`n", $utf8)
    Reconcile
    break
  }
  default { Show-Usage }
}
